// parseHexColor parses a hex color string in various formats:
// - 3 digits: "abc" or "#abc" -> #aabbcc
// - 4 digits: "abcd" or "#abcd" -> #aabbccdd
// - 6 digits: "a1b2c3" or "#a1b2c3" -> #a1b2c3
// - 8 digits: "a1b2c3f4" or "#a1b2c3f4" -> #a1b2c3f4
func parseHexColor(hex string) (color.Color, error) {
	// Remove # prefix if present
	hex = strings.TrimPrefix(hex, "#")

	var r, g, b, a uint8
	a = 0xff // default to opaque

	switch len(hex) {
	case 3:
		// RGB shorthand: abc -> aabbcc
		vals, err := parseHexDigits(hex)
		if err != nil {
			return color.NRGBA{}, err
		}
		r = vals[0] | (vals[0] << 4)
		g = vals[1] | (vals[1] << 4)
		b = vals[2] | (vals[2] << 4)

	case 4:
		// RGBA shorthand: abcd -> aabbccdd
		vals, err := parseHexDigits(hex)
		if err != nil {
			return color.NRGBA{}, err
		}
		r = vals[0] | (vals[0] << 4)
		g = vals[1] | (vals[1] << 4)
		b = vals[2] | (vals[2] << 4)
		a = vals[3] | (vals[3] << 4)

	case 6:
		// RRGGBB
		val, err := strconv.ParseUint(hex, 16, 32)
		if err != nil {
			return color.NRGBA{}, err
		}
		r = uint8((val >> 16) & 0xff)
		g = uint8((val >> 8) & 0xff)
		b = uint8(val & 0xff)

	case 8:
		// RRGGBBAA
		val, err := strconv.ParseUint(hex, 16, 64)
		if err != nil {
			return color.NRGBA{}, err
		}
		r = uint8((val >> 24) & 0xff)
		g = uint8((val >> 16) & 0xff)
		b = uint8((val >> 8) & 0xff)
		a = uint8(val & 0xff)

	default:
		return color.NRGBA{}, fmt.Errorf("invalid hex color format: %s", hex)
	}

	return color.NRGBA{R: r, G: g, B: b, A: a}, nil
}

func parseHexDigits(hex string) ([]uint8, error) {
	vals := make([]uint8, len(hex))
	for i, ch := range hex {
		var val uint8
		switch {
		case ch >= '0' && ch <= '9':
			val = uint8(ch - '0')
		case ch >= 'a' && ch <= 'f':
			val = uint8(ch - 'a' + 10)
		case ch >= 'A' && ch <= 'F':
			val = uint8(ch - 'A' + 10)
		default:
			return nil, fmt.Errorf("invalid hex digit: %c", ch)
		}
		vals[i] = val
	}
	return vals, nil
}

func loadResourceFromURI(uriStr string) (fyne.Resource, error) {
	uri, err := storage.ParseURI(uriStr)
	if err != nil {
		return nil, err
	}

	reader, err := storage.Reader(uri)
	if err != nil {
		return nil, err
	}
	defer reader.Close()

	data, err := io.ReadAll(reader)
	if err != nil {
		return nil, err
	}

	return fyne.NewStaticResource(uri.Name(), data), nil
}

