package binding

import (
	"fmt"
	"sync"

	"fyne.io/fyne/v2"
	"fyne.io/fyne/v2/storage"
)

// sprintfBinding is a String binding that formats multiple source bindings
type sprintfBinding struct {
	base
	format  string
	sources []DataItem
	value   string
	err     error
	lock    sync.RWMutex
}

// NewSprintf creates a formatted string binding that combines multiple data bindings.
// When any source binding changes, the formatted string automatically updates using fmt.Sprintf.
// The binding supports reverse parsing via Set() using fmt.Sscanf semantics.
//
// Since: 2.5
func NewSprintf(format string, bindings ...DataItem) String {
	s := &sprintfBinding{
		format:  format,
		sources: bindings,
	}

	// Add listeners to all source bindings
	listener := NewDataListener(func() {
		s.updateValue()
	})

	for _, b := range bindings {
		b.AddListener(listener)
	}

	// Initial update
	s.updateValue()

	return s
}

func (s *sprintfBinding) updateValue() {
	s.lock.Lock()
	defer s.lock.Unlock()

	// Collect all source values
	values := make([]interface{}, len(s.sources))
	for i, source := range s.sources {
		val, err := getBindingValue(source)
		if err != nil {
			s.err = err
			s.lock.Unlock()
			s.trigger()
			s.lock.Lock()
			return
		}
		values[i] = val
	}

	// Format the string
	s.value = fmt.Sprintf(s.format, values...)
	s.err = nil

	s.lock.Unlock()
	s.trigger()
	s.lock.Lock()
}

func (s *sprintfBinding) Get() (string, error) {
	s.lock.RLock()
	defer s.lock.RUnlock()
	return s.value, s.err
}

func (s *sprintfBinding) Set(str string) error {
	// Parse the string back into source bindings using fmt.Sscanf
	values := make([]interface{}, len(s.sources))
	for i, source := range s.sources {
		values[i] = makePointerForBinding(source)
	}

	n, err := fmt.Sscanf(str, s.format, values...)
	if err != nil {
		return err
	}
	if n != len(s.sources) {
		return fmt.Errorf("format did not match all values")
	}

	// Set all source bindings
	for i, source := range s.sources {
		if err := setBindingValue(source, values[i]); err != nil {
			return err
		}
	}

	return nil
}

// getBindingValue retrieves the value from a DataItem binding
func getBindingValue(item DataItem) (interface{}, error) {
	switch b := item.(type) {
	case Bool:
		return b.Get()
	case Bytes:
		return b.Get()
	case Float:
		return b.Get()
	case Int:
		return b.Get()
	case Rune:
		return b.Get()
	case String:
		return b.Get()
	case URI:
		u, err := b.Get()
		if err != nil {
			return nil, err
		}
		if u == nil {
			return "", nil
		}
		return u.String(), nil
	default:
		return nil, fmt.Errorf("unsupported binding type")
	}
}

// makePointerForBinding creates an appropriate pointer for scanning
func makePointerForBinding(item DataItem) interface{} {
	switch item.(type) {
	case Bool:
		var v bool
		return &v
	case Bytes:
		var v []byte
		return &v
	case Float:
		var v float64
		return &v
	case Int:
		var v int
		return &v
	case Rune:
		var v rune
		return &v
	case String:
		var v string
		return &v
	case URI:
		var v string
		return &v
	default:
		var v interface{}
		return &v
	}
}

// setBindingValue sets the value on a DataItem binding
func setBindingValue(item DataItem, value interface{}) error {
	switch b := item.(type) {
	case Bool:
		if v, ok := value.(*bool); ok {
			return b.Set(*v)
		}
		return fmt.Errorf("type mismatch for Bool binding")
	case Bytes:
		// Bytes cannot be round-tripped via Sscanf
		return fmt.Errorf("Bytes binding cannot be set via formatted string")
	case Float:
		if v, ok := value.(*float64); ok {
			return b.Set(*v)
		}
		return fmt.Errorf("type mismatch for Float binding")
	case Int:
		if v, ok := value.(*int); ok {
			return b.Set(*v)
		}
		return fmt.Errorf("type mismatch for Int binding")
	case Rune:
		if v, ok := value.(*rune); ok {
			return b.Set(*v)
		}
		return fmt.Errorf("type mismatch for Rune binding")
	case String:
		if v, ok := value.(*string); ok {
			return b.Set(*v)
		}
		return fmt.Errorf("type mismatch for String binding")
	case URI:
		if v, ok := value.(*string); ok {
			uri, err := storage.ParseURI(*v)
			if err != nil {
				return err
			}
			return b.Set(uri)
		}
		return fmt.Errorf("type mismatch for URI binding")
	default:
		return fmt.Errorf("unsupported binding type")
	}
}

// StringToStringWithFormat wraps a String binding with a format.
// If the format is "%s" (identity), returns the original binding directly.
//
// Since: 2.5
func StringToStringWithFormat(str String, format string) String {
	if format == "%s" {
		return str
	}
	return NewSprintf(format, str)
}

