		}
		return fmt.Errorf("type mismatch for Rune binding")
	case String:
		if v, ok := value.(*string); ok {
			return b.Set(*v)
		}
		return fmt.Errorf("type mismatch for String binding")
	case URI:
		if v, ok := value.(*string); ok {
			uri, err := storage.ParseURI(*v)
			if err != nil {
				return err
			}
			return b.Set(uri)
		}
		return fmt.Errorf("type mismatch for URI binding")
	default:
		return fmt.Errorf("unsupported binding type")
	}
}

// StringToStringWithFormat wraps a String binding with a format.
// If the format is "%s" (identity), returns the original binding directly.
//
// Since: 2.5
func StringToStringWithFormat(str String, format string) String {
	if format == "%s" {
		return str
	}
	return NewSprintf(format, str)
}

