package widget

import (
	"fyne.io/fyne/v2"
	"fyne.io/fyne/v2/theme"
)

// NewPasswordEntry creates an Entry with a password reveal icon in the ActionItem slot.
// The reveal icon toggles password visibility when tapped.
//
// Since: 2.5
func NewPasswordEntry() *Entry {
	e := NewEntry()
	e.Password = true
	e.ActionItem = newPasswordRevealer(e)
	return e
}

// NewPasswordEntryWithData creates a data-bound Entry with password reveal toggle.
//
// Since: 2.5
func NewPasswordEntryWithData(data binding.String) *Entry {
	e := NewEntryWithData(data)
	e.Password = true
	e.ActionItem = newPasswordRevealer(e)
	return e
}

type passwordRevealer struct {
	BaseWidget
	entry   *Entry
	icon    *fyne.Resource
	button  *Button
}

func newPasswordRevealer(e *Entry) fyne.CanvasObject {
	pr := &passwordRevealer{entry: e}
	pr.ExtendBaseWidget(pr)
	return pr
}

func (pr *passwordRevealer) CreateRenderer() fyne.WidgetRenderer {
	pr.button = NewButtonWithIcon("", theme.VisibilityOffIcon(), func() {
		pr.toggle()
	})
	pr.button.Importance = LowImportance

	return NewSimpleRenderer(pr.button)
}

func (pr *passwordRevealer) toggle() {
	if pr.entry == nil {
		return
	}

	pr.entry.Password = !pr.entry.Password

	if pr.entry.Password {
		pr.button.SetIcon(theme.VisibilityOffIcon())
	} else {
		pr.button.SetIcon(theme.VisibilityIcon())
	}

	pr.entry.Refresh()
}

func (pr *passwordRevealer) MinSize() fyne.Size {
	if pr.button == nil {
		pr.CreateRenderer()
	}
	return pr.button.MinSize()
}

