package validation

import (
	"errors"
	"net/mail"
	"net/url"
	"regexp"
	"strings"
)

var (
	// ErrInvalidEmail is returned when email validation fails
	ErrInvalidEmail = errors.New("invalid email address")
	// ErrInvalidURL is returned when URL validation fails
	ErrInvalidURL = errors.New("invalid URL")
	// ErrLengthTooShort is returned when string is shorter than minimum
	ErrLengthTooShort = errors.New("string length too short")
	// ErrLengthTooLong is returned when string is longer than maximum
	ErrLengthTooLong = errors.New("string length too long")
	// ErrInvalidPhoneNumber is returned when phone validation fails
	ErrInvalidPhoneNumber = errors.New("invalid phone number")
)

// NewEmail returns a validator that checks for valid email format using Go's net/mail parser.
//
// Since: 2.5
func NewEmail() func(string) error {
	return func(text string) error {
		if text == "" {
			return nil
		}
		_, err := mail.ParseAddress(text)
		if err != nil {
			return ErrInvalidEmail
		}
		return nil
	}
}

// NewURL returns a validator that checks for valid URL format.
// If requireScheme is true, the URL must have a scheme (e.g., "http://").
//
// Since: 2.5
func NewURL(requireScheme bool) func(string) error {
	return func(text string) error {
		if text == "" {
			return nil
		}
		u, err := url.Parse(text)
		if err != nil {
			return ErrInvalidURL
		}
		if requireScheme && u.Scheme == "" {
			return ErrInvalidURL
		}
		return nil
	}
}

// NewLength returns a validator that checks string length is between min and max (inclusive).
// Use -1 for min or max to disable that bound.
//
// Since: 2.5
func NewLength(min, max int) func(string) error {
	return func(text string) error {
		length := len([]rune(text))
		if min >= 0 && length < min {
			return ErrLengthTooShort
		}
		if max >= 0 && length > max {
			return ErrLengthTooLong
		}
		return nil
	}
}

// NewPhoneNumber returns a validator for phone numbers.
// This uses a simple pattern that accepts common formats.
// For strict validation, use NewRegexp with a specific pattern.
//
// Since: 2.5
func NewPhoneNumber() func(string) error {
	// Pattern accepts: +1234567890, (123) 456-7890, 123-456-7890, etc.
	pattern := `^[\d\s\-\(\)\+\.]+$`
	re := regexp.MustCompile(pattern)

	return func(text string) error {
		if text == "" {
			return nil
		}
		// Remove common separators for digit count check
		digits := strings.Map(func(r rune) rune {
			if r >= '0' && r <= '9' {
				return r
			}
			return -1
		}, text)

		// Most phone numbers have 7-15 digits
		if len(digits) < 7 || len(digits) > 15 {
			return ErrInvalidPhoneNumber
		}

		if !re.MatchString(text) {
			return ErrInvalidPhoneNumber
		}
		return nil
	}
}

// Chain returns a validator that runs all provided validators in sequence.
// Returns the first error encountered, or nil if all pass.
//
// Since: 2.5
func Chain(validators ...func(string) error) func(string) error {
	return func(text string) error {
		for _, v := range validators {
			if err := v(text); err != nil {
				return err
			}
		}
		return nil
	}
}

