func (e *Entry) MinSize() fyne.Size {
	e.ExtendBaseWidget(e)

	min := e.BaseWidget.MinSize()

	// Override height for multi-line entries when minRowsVisible is set
	if e.MultiLine && e.minRowsVisible > 0 {
		charSize := e.textProvider().charMinSize(e.Password, e.TextStyle)
		rowHeight := charSize.Height
		// Calculate height for the specified number of rows, including padding between rows
		minHeight := float32(e.minRowsVisible)*rowHeight + float32(e.minRowsVisible-1)*theme.Padding()
		// Add inset padding (top + bottom)
		minHeight += theme.Padding() * 4

		if minHeight > min.Height {
			min.Height = minHeight
		} else if minHeight < min.Height {
			// If the calculated height is less than the current min, use the specified rows
			min.Height = minHeight
		}
	}

	if e.ActionItem != nil {
		min = min.Add(fyne.NewSize(theme.IconInlineSize()+theme.Padding(), 0))
	}
	if e.Validator != nil {
		min = min.Add(fyne.NewSize(theme.IconInlineSize()+theme.Padding(), 0))
	}

	return min
}

