// Chain returns a validator that runs all provided validators in sequence.
// Returns the first error encountered, or nil if all pass.
//
// Since: 2.5
func Chain(validators ...func(string) error) func(string) error {
	return func(text string) error {
		for _, v := range validators {
			if err := v(text); err != nil {
				return err
			}
		}
		return nil
	}
}

// NewAllStrings returns a validator that checks if the input contains all specified substrings.
// The check is case-sensitive.
//
// Since: 2.5
func NewAllStrings(required ...string) func(string) error {
	return func(text string) error {
		for _, req := range required {
			if !strings.Contains(text, req) {
				return errors.New("missing required substring: " + req)
			}
		}
		return nil
	}
}

