// Package desktop provides desktop specific driver functionality.
package desktop

import "fyne.io/fyne/v2"

// Driver represents the extended capabilities of a desktop driver
type Driver interface {
	// Create a new borderless window that is centered on screen
	CreateSplashWindow() fyne.Window
}

// Lifecycle represents hooks for desktop application lifecycle events.
// These callbacks allow applications to respond to system-level events
// such as sleep, wake, and shutdown.
//
// Since: 2.5
type Lifecycle interface {
	// SetOnSystemSleep sets a callback that is invoked when the system is about to sleep.
	// This allows the app to save state or pause operations before suspension.
	SetOnSystemSleep(func())

	// SetOnSystemWake sets a callback that is invoked when the system wakes from sleep.
	// This allows the app to resume operations or refresh state after suspension.
	SetOnSystemWake(func())

	// SetOnSystemShutdown sets a callback that is invoked when the system is shutting down.
	// This allows the app to perform cleanup before termination.
	// Return true to allow shutdown, false to attempt to cancel (may not always work).
	SetOnSystemShutdown(func() bool)
}

